import { randomUUID } from "node:crypto";
import {
  DomainError,
  Project,
  Task,
  TaskFilter,
  TaskRepository,
  TaskStatus,
  User,
  taskStatuses,
} from "../domain/task";

export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: TaskStatus;
  assigneeId?: string;
}

export class TaskService {
  public constructor(private readonly repository: TaskRepository) {}

  public createUser(name: string): User {
    this.requireNonEmpty(name, "User name");
    const user = { id: randomUUID(), name: name.trim() };
    this.repository.addUser(user);
    return user;
  }

  public createProject(name: string): Project {
    this.requireNonEmpty(name, "Project name");
    const project = { id: randomUUID(), name: name.trim() };
    this.repository.addProject(project);
    return project;
  }

  public createTask(projectId: string, input: CreateTaskInput): Task {
    this.requireProject(projectId);
    this.requireNonEmpty(input.title, "Task title");
    this.requireNonEmpty(input.description, "Task description");
    if (input.assigneeId !== undefined) {
      this.requireUser(input.assigneeId);
    }
    if (input.dueDate !== undefined && Number.isNaN(Date.parse(input.dueDate))) {
      throw new DomainError("VALIDATION", "Due date must be a valid date string");
    }
    const status = input.status ?? "todo";
    if (!taskStatuses.includes(status)) {
      throw new DomainError("VALIDATION", "Task status is invalid");
    }
    const task: Task = {
      id: randomUUID(),
      projectId,
      title: input.title.trim(),
      description: input.description.trim(),
      ...(input.dueDate === undefined ? {} : { dueDate: input.dueDate }),
      status,
      ...(input.assigneeId === undefined ? {} : { assigneeId: input.assigneeId }),
    };
    this.repository.addTask(task);
    return task;
  }

  public listTasks(projectId: string, filter: TaskFilter): Task[] {
    this.requireProject(projectId);
    if (filter.status !== undefined && !taskStatuses.includes(filter.status)) {
      throw new DomainError("VALIDATION", "Task status is invalid");
    }
    if (filter.assigneeId !== undefined) {
      this.requireUser(filter.assigneeId);
    }
    return this.repository.tasksForProject(projectId, filter);
  }

  public markDone(taskId: string): Task {
    const task = this.repository.findTask(taskId);
    if (task === undefined) {
      throw new DomainError("NOT_FOUND", "Task not found");
    }
    if (task.status === "done") {
      throw new DomainError("CONFLICT", "Task is already done");
    }
    task.status = "done";
    return task;
  }

  private requireProject(projectId: string): Project {
    const project = this.repository.findProject(projectId);
    if (project === undefined) {
      throw new DomainError("NOT_FOUND", "Project not found");
    }
    return project;
  }

  private requireUser(userId: string): User {
    const user = this.repository.findUser(userId);
    if (user === undefined) {
      throw new DomainError("NOT_FOUND", "Assignee not found");
    }
    return user;
  }

  private requireNonEmpty(value: string, label: string): void {
    if (typeof value !== "string" || value.trim() === "") {
      throw new DomainError("VALIDATION", `${label} is required`);
    }
  }
}

